class Solution:
    def countConnectedEvenSubgraphs(self, nums: List[int], edges: List[List[int]]) -> int:
        n = len(nums)
        adj = [0] * n
        for u, v in edges:
            adj[u] |= 1 << v
            adj[v] |= 1 << u
        ans = 0
        for m in range(1, 1 << n):
            s, t = 0, m
            while t:
                b = t & -t
                s += nums[b.bit_length() - 1]
                t ^= b
            if s % 2:
                continue
            seen = m & -m
            stack = [seen]
            while stack:
                cur = stack.pop()
                nxt = adj[cur.bit_length() - 1] & m
                while nxt:
                    b = nxt & -nxt
                    if not seen & b:
                        seen |= b
                        stack.append(b)
                    nxt ^= b
            if seen == m:
                ans += 1
        return ans

