    def countConnectedEvenSubgraphs(self, nums: List[int], edges: List[List[int]]) -> int:
        n = len(nums)
        adj = [0] * n
        for u, v in edges:
            adj[u] |= 1 << v
            adj[v] |= 1 << u
        ones = sum(1 << i for i in range(n) if nums[i])
        size = 1 << n
        conn = [False] * size
        ans = 0
        for m in range(1, size):
            lb = m & -m
            if m == lb:
                conn[m] = True
            else:
                t, ok = m ^ lb, False
                while t:
                    b = t & -t
                    t ^= b
                    rest = m ^ b
                    if conn[rest] and (adj[b.bit_length() - 1] & rest):
                        ok = True
                        break
                conn[m] = ok
            if conn[m] and bin(m & ones).count("1") % 2 == 0:
                ans += 1
        return ans

